package com.cvp.maintenance.adapter.outbound.persistence;
import com.cvp.maintenance.domain.OutboxStatus; import jakarta.persistence.*; import java.time.*; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="outbox_event") public class OutboxEventEntity { @Id public UUID id; @Column(name="aggregate_type", nullable=false,length=64) public String aggregateType; @Column(name="aggregate_id",nullable=false) public UUID aggregateId; @Column(name="event_type",nullable=false,length=128) public String eventType; @Column(name="schema_version",nullable=false) public int schemaVersion; @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") public String payload; @Column(name="correlation_id") public UUID correlationId; @Enumerated(EnumType.STRING) @Column(name="publication_status",nullable=false,length=16) public OutboxStatus publicationStatus; @Column(name="attempt_count",nullable=false) public int attemptCount; @Column(name="next_attempt_at",nullable=false) public Instant nextAttemptAt; @Column(name="claimed_at") public Instant claimedAt; @Column(name="claim_token") public UUID claimToken; @Column(name="claim_expires_at") public Instant claimExpiresAt; @Column(name="published_at") public Instant publishedAt; @Column(name="last_failure_code",length=64) public String lastFailureCode; @Column(name="created_at",nullable=false) public Instant createdAt; public OutboxEventEntity(){} }
